66	fn invalidate_on_non_cancellation(operation: &mut Option<AffinityAcquire>, error: &Error) {
67	    if is_cancelled(error) {
68	        return;
69	    }
70	    if let Some(operation) = operation.take() {
71	        operation.invalidate();
72	    }
