79	fn monitor_response_stream<Sel>(
80	    mut response_stream: ManyOut<Annotated<LLMEngineOutput>>,
81	    context: Arc<dyn AsyncEngineContext>,
82	    mut guard: RequestGuard<Sel>,
83	) -> impl futures::Stream<Item = Annotated<LLMEngineOutput>> + Send
84	where
85	    Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
86	{
87	    async_stream::stream! {
88	        // Keep one cancellation future alive for the whole response stream. Calling
89	        // `stopped()` for every item repeatedly clones and polls a watch receiver.
90	        let stopped = context.stopped();
91	        tokio::pin!(stopped);
92	
93	        let completed = loop {
94	            tokio::select! {
95	                biased;
96	
97	                _ = &mut stopped => {
98	                    tracing::debug!(request_id = context.id(), "Request cancelled, ending stream");
99	                    break false;
100	                }
101	
102	                item = response_stream.next() => {
103	                    let Some(item) = item else {
104	                        break true;
105	                    };
106	                    let item_failed = response_item_failed(&item);
107	                    guard.on_item(&item).await;
108	                    if item_failed {
109	                        guard.record_migration_failure(item.error.clone());
110	                        // Release the failed attempt before Migration can observe
111	                        // the item and start another one. This keeps serialized
112	                        // retries free of stale-cleanup ABA races.
113	                        guard.abort().await;
114	                        yield item;
115	                        break false;
116	                    }
117	                    yield item;
118	                }
119	            }
120	        };
121	
122	        if completed {
123	            guard.finish().await;
124	        } else {
125	            guard.abort().await;
126	        }
127	    }
128	}
