183	/// Owns request routing from worker selection through response cleanup.
184	///
185	/// [`PushRouter`] owns discovery, fault detection, and transport. [`KvRouter`]
186	/// owns optional KV candidate state. `RoutingHost` owns the common request
187	/// lifecycle regardless of which policy selected the worker.
188	pub struct RoutingHost<Sel = DefaultWorkerSelector>
189	where
190	    Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
191	{
192	    inner: PushRouter<PreprocessedRequest, Annotated<LLMEngineOutput>>,
193	    policy: RoutingPolicy<Sel>,
194	    request_metrics: Arc<RouterRequestMetrics>,
195	    affinity: Option<AffinityCoordinator>,
196	    hosted_occupancy: Option<HostedOccupancy>,
197	    lora: Option<LoraRouting>,
198	}
