257	    pub(crate) fn new_builtin_with_capabilities(
258	        inner: PushRouter<PreprocessedRequest, Annotated<LLMEngineOutput>>,
259	        affinity: Option<AffinityCoordinator>,
260	        lora: Option<(Arc<LoraFilter>, Arc<LoadEstimator>)>,
261	    ) -> Result<Self, Error> {
262	        if affinity.is_some() && lora.is_some() {
263	            anyhow::bail!("session affinity and LoRA filtering cannot both be enabled");
264	        }
265	        let policy = match inner.router_mode() {
266	            RouterMode::Direct => RoutingPolicy::Direct,
267	            RouterMode::DeviceAwareWeighted => RoutingPolicy::DeviceAwareWeighted,
268	            mode => {
269	                RoutingPolicy::Builtin(BuiltinWorkerSelector::new(mode).ok_or_else(|| {
270	                    anyhow::anyhow!("{mode:?} routing is not a first-party policy")
271	                })?)
272	            }
273	        };
274	        let required_worker_inputs = match &policy {
275	            RoutingPolicy::Builtin(selector) => selector.required_worker_inputs(),
276	            RoutingPolicy::DeviceAwareWeighted => WorkerInputs::OCCUPANCY,
277	            RoutingPolicy::Direct => WorkerInputs::NONE,
278	            RoutingPolicy::Kv(_) => unreachable!(),
279	        };
280	        let hosted_occupancy = matches!(&policy, RoutingPolicy::Builtin(_))
281	            .then_some(required_worker_inputs.contains(WorkerInputs::OCCUPANCY))
282	            .unwrap_or(false)
283	            .then(|| HostedOccupancy::new(&inner))
284	            .transpose()?;
285	        if lora.is_some()
286	            && !matches!(
287	                inner.router_mode(),
288	                RouterMode::RoundRobin | RouterMode::Random
289	            )
290	        {
291	            anyhow::bail!(
292	                "LoRA filtering is unsupported with {:?} routing",
293	                inner.router_mode()
294	            );
295	        }
296	        let lora_selector = lora.as_ref().map(|_| {
297	            BuiltinWorkerSelector::new(inner.router_mode())
298	                .expect("LoRA routing mode was validated above")
299	        });
300	        let request_metrics =
301	            RouterRequestMetrics::from_component(inner.client.endpoint.component());
302	        Ok(Self {
303	            inner,
304	            policy,
305	            request_metrics,
306	            affinity,
307	            hosted_occupancy,
308	            lora: lora
309	                .zip(lora_selector)
310	                .map(|((filter, load_estimator), selector)| LoraRouting {
311	                    filter,
312	                    load_estimator,
313	                    selector,
314	                }),
315	        })
316	    }
