347	    pub(crate) fn peek_next_worker(&self) -> Option<u64> {
348	        match &self.policy {
349	            RoutingPolicy::Builtin(selector) => match &self.hosted_occupancy {
350	                Some(occupancy) => occupancy.peek(&self.inner, selector),
351	                None => self
352	                    .inner
353	                    .with_selectable_worker_ids(|ids| {
354	                        selector.peek_worker(
355	                            dynamo_kv_router::selector::WorkerSelectionInput::hosted(ids, None),
356	                        )
357	                    })
358	                    .ok()
359	                    .and_then(Result::ok),
360	            },
361	            RoutingPolicy::DeviceAwareWeighted => self.inner.peek_next_worker(),
362	            RoutingPolicy::Direct => None,
363	            RoutingPolicy::Kv(_) => None,
364	        }
365	    }
