367	    pub(crate) fn query_affinity_target(
368	        &self,
369	        request: &SingleIn<PreprocessedRequest>,
370	        phase: RequestPhase,
371	    ) -> Result<Option<AffinityTarget>, Error> {
372	        let Some(affinity) = self.affinity.as_ref() else {
