382	    fn affinity_target_requires_rebind(
383	        &self,
384	        request: &PreprocessedRequest,
385	        target: AffinityTarget,
386	    ) -> bool {
387	        if request
388	            .migration_state
389	            .as_ref()
390	            .is_some_and(|state| state.excluded_worker_ids().contains(&target.worker_id))
391	        {
392	            return true;
393	        }
394	        if !self
395	            .inner
396	            .client
397	            .instance_ids_avail()
398	            .contains(&target.worker_id)
399	        {
400	            return true;
401	        }
402	        let Some(kv_router) = self.kv_router_if_enabled() else {
403	            return false;
404	        };
405	        let workers = kv_router.workers_with_configs.borrow();
406	        let Some(config) = workers.get(&target.worker_id) else {
407	            return true;
408	        };
409	        let Some(dp_rank) = target.dp_rank else {
410	            return false;
411	        };
412	        let start = config.data_parallel_start_rank();
413	        let end = start.saturating_add(config.data_parallel_size());
414	        !(start..end).contains(&dp_rank)
415	    }
