417	    async fn select_with_session_affinity<T, Select, SelectionFuture>(
418	        &self,
419	        request: &SingleIn<PreprocessedRequest>,
420	        phase: RequestPhase,
421	        is_query_only: bool,
422	        mut select: Select,
423	    ) -> Result<(T, Option<AffinityAcquire>), Error>
424	    where
425	        Select: FnMut(Option<AffinityTarget>) -> SelectionFuture,
426	        SelectionFuture: Future<Output = Result<T, Error>>,
427	    {
428	        let Some(affinity) = self.affinity.as_ref() else {
429	            return Ok((select(None).await?, None));
430	        };
431	        let Some(session_id) = affinity_id(request)? else {
432	            return Ok((select(None).await?, None));
433	        };
434	        let explicit = explicit_target(request, phase)?;
435	        if is_query_only {
436	            let target = affinity.query_target(&session_id, explicit)?;
437	            return Ok((select(target).await?, None));
438	        }
439	
440	        let request_context = request.context();
441	        let operation = affinity
442	            .acquire_with_context(&session_id, explicit, request_context.as_ref())
443	            .await?;
444	        let target = operation.target();
445	        match select(target).await {
446	            Ok(selection) => Ok((selection, Some(operation))),
447	            Err(error) if is_cancelled(&error) => Err(error),
448	            Err(_)
449	                if explicit.is_none()
450	                    && target.is_some_and(|target| {
451	                        self.affinity_target_requires_rebind(request.content(), target)
452	                    }) =>
453	            {
454	                operation.invalidate();
455	                let retry = affinity
456	                    .acquire_with_context(&session_id, None, request_context.as_ref())
457	                    .await?;
458	                match select(retry.target()).await {
459	                    Ok(selection) => Ok((selection, Some(retry))),
460	                    Err(retry_error) => Err(retry_error),
461	                }
462	            }
463	            Err(error) => Err(error),
464	        }
465	    }
