467	    pub(crate) async fn select_and_dispatch_prefill<M, F>(
468	        &self,
469	        request: SingleIn<PreprocessedRequest>,
470	        prepare: F,
471	    ) -> Result<(M, ManyOut<Annotated<LLMEngineOutput>>), Error>
472	    where
473	        F: FnOnce(&mut PreprocessedRequest, AffinityTarget) -> Result<M, Error>,
474	    {
475	        match &self.policy {
476	            RoutingPolicy::Kv(_) => self.select_and_dispatch_kv_prefill(request, prepare).await,
477	            RoutingPolicy::Builtin(_)
478	            | RoutingPolicy::Direct
479	            | RoutingPolicy::DeviceAwareWeighted => {
480	                self.select_and_dispatch_builtin(request, RequestPhase::Prefill, prepare)
481	                    .await
482	            }
483	        }
484	    }
485	}
