487	#[async_trait]
488	impl<Sel> AsyncEngine<SingleIn<PreprocessedRequest>, ManyOut<Annotated<LLMEngineOutput>>, Error>
489	    for RoutingHost<Sel>
490	where
491	    Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
492	{
493	    /// Generate a request through the selected routing plane.
494	    ///
495	    /// On the KV plane, `query_instance_id` performs an advisory selection:
496	    ///    - Returns the best matching worker ID without routing the request
497	    ///    - Does NOT update any router local states
498	    ///    - Response includes worker_instance_id and token_data annotations
499	    ///
500	    /// The built-in Random and RoundRobin plane has no KV query path: it selects a worker and
501	    /// dispatches the request. `query_instance_id` is therefore a KV-routing/disaggregation
502	    /// annotation, not a request-execution suppressor for those modes.
503	    ///
504	    /// On the KV plane, a phase-specific worker or `backend_instance_id`:
505	    ///    - Query-only requests return that worker selection without state updates
506	    ///    - Requests route through the scheduler as an exact pin when dp_rank is resolved
507	    ///    - If dp_rank cannot be resolved, the request is rejected instead of treating rank 0 as a sentinel
508	    ///
509	    /// Otherwise, KV routing:
510	    ///    - Finds the best worker based on KV cache overlap
511	    ///    - Updates router states to track the request
512	    ///    - Routes to the selected worker
513	    ///
514	    /// The router state updates include tracking active sequences and managing
515	    /// prefill/completion lifecycle for proper KV cache management.
516	    async fn generate(
517	        &self,
518	        request: SingleIn<PreprocessedRequest>,
519	    ) -> Result<ManyOut<Annotated<LLMEngineOutput>>, Error> {
520	        if !matches!(&self.policy, RoutingPolicy::Kv(_)) {
521	            let phase = request
522	                .tracker
523	                .as_ref()
524	                .map(|tracker| tracker.phase())
525	                .unwrap_or(RequestPhase::Aggregated);
526	            return self
527	                .select_and_dispatch_builtin(request, phase, |_, _| Ok(()))
528	                .await
529	                .map(|(_, stream)| stream);
530	        }
531	
532	        let is_query_only = request.get_annotation_value("query_instance_id").is_some();
533	        let phase = request
534	            .tracker
535	            .as_ref()
536	            .map(|tracker| tracker.phase())
537	            .unwrap_or(RequestPhase::Aggregated);
538	        let phase_label = phase.to_string();
539	        let route_guard = StageGuard::new(STAGE_ROUTE, &phase_label);
540	        let (mut selection, mut operation) = self
541	            .select_with_affinity(&request, phase, is_query_only)
542	            .await?;
543	        if is_query_only {
544	            let routing_parts = RoutingRequestParts::new(&request);
545	            if let Some(ref tracker) = request.tracker {
546	                let isl_blocks = routing_parts
547	                    .token_ids
548	                    .len()
549	                    .div_ceil(self.kv_router().block_size() as usize);
550	                tracker.record_kv_hit(selection.effective_overlap_blocks, isl_blocks);
551	                tracker.record_isl(routing_parts.token_ids.len(), Some(selection.cached_tokens));
552	                tracker.record_worker(
553	                    selection.worker.worker_id,
554	                    Some(selection.worker.dp_rank),
555	                    self.kv_router().worker_type(),
556	                );
557	                tracker.record_router_queue_depth(self.kv_router().pending_count());
558	            }
559	            self.request_metrics
560	                .input_sequence_tokens
561	                .observe(request.token_ids.len() as f64);
562	            let stream_context = request.context().clone();
563	            let worker_id_info = request
564	                .tracker
565	                .as_ref()
566	                .and_then(|tracker| tracker.get_worker_info());
567	
568	            tracing::trace!(
569	                ?phase,
570	                worker_id = selection.worker.worker_id,
571	                ?worker_id_info,
572	                "Returning worker selection (query-only mode)"
573	            );
574	
575	            let output = LLMEngineOutput {
576	                routing_data: Some(RoutingData {
577	                    worker_id: worker_id_info,
578	                    token_ids: Some(request.token_ids.clone()),
579	                    ..Default::default()
580	                }),
581	                ..Default::default()
582	            };
583	            let response = Annotated::from_data(output);
584	            let stream = stream::iter(vec![response]);
585	            return Ok(ResponseStream::new(Box::pin(stream), stream_context));
586	        }
587	
588	        let guard = match self.track_selection(&request, &mut selection, false).await {
589	            Ok(guard) => guard,
590	            Err(error) => {
591	                invalidate_on_non_cancellation(&mut operation, &error);
592	                return Err(error);
593	            }
594	        };
595	        drop(route_guard);
596	        let selected_target = route_target(selection.worker);
597	        let stream = match self
598	            .dispatch_selection(request, selection, guard, operation.is_some())
599	            .await
600	        {
601	            Ok(stream) => stream,
602	            Err(error) => {
603	                invalidate_on_non_cancellation(&mut operation, &error);
604	                return Err(error);
605	            }
606	        };
607	        match operation {
608	            Some(operation) => operation.into_stream(selected_target, stream),
609	            None => Ok(stream),
610	        }
611	    }
612	}
