614	fn response_item_failed(item: &Annotated<LLMEngineOutput>) -> bool {
615	    item.error.is_some()
616	        || item.event.as_deref() == Some("error")
617	        || item
618	            .data
619	            .as_ref()
620	            .and_then(|data| data.finish_reason.as_ref())
621	            .is_some_and(|reason| {
622	                matches!(reason, FinishReason::Error(_) | FinishReason::Cancelled)
623	            })
624	}
