84	
85	        // `skip_initial_worker_wait` only controls boot-time blocking. The scheduler must
86	        // keep monitoring runtime config changes so late-joining workers enter routing.
87	        let watch_worker_configs = true;
88	
89	        let profile = kv_router_config
90	            .policy_profile(model_name)
91	            .map_err(|error| KvSchedulerError::InitFailed(error.to_string()))?;
92	        let queue_recheck_interval = kv_router_config.router_queue_recheck_interval();
93	        let metric_model = model_name.unwrap_or("unknown");
94	        let queue_metrics = profile
95	            .classes()
96	            .iter()
97	            .map(|class| ROUTER_QUEUE_METRICS.handles(metric_model, worker_type, &class.name))
98	            .collect::<Vec<_>>();
99	        let queue_metric_indices = profile
100	            .classes()
101	            .iter()
102	            .enumerate()
103	            .map(|(index, class)| (class.name.clone(), index))
104	            .collect();
105	
106	        let inner = Arc::new(LocalScheduler::new_with_policy_profile(
107	            slots,
108	            workers_with_configs.clone(),
109	            profile,
110	            block_size,
111	            selector,
112	            prefill_load_estimator,
113	            overlap_scores_refresh,
114	            overloaded_worker_provider,
115	            available_worker_provider,
116	            queue_recheck_interval,
117	            kv_router_config.router_track_prefill_tokens,
118	            cancellation_token.child_token(),
119	            worker_type,
120	            watch_worker_configs,
121	        )?);
122	        if worker_type == WORKER_TYPE_PREFILL {
123	            let locality_observer: NonMaxOverlapSelectionObserver =
124	                Arc::new(move |request_id, selection| {
125	                    let overlap_blocks_lost = selection.overlap_blocks_lost();
126	                    if let Some(metrics) = RouterRequestMetrics::get() {
127	                        metrics.observe_non_max_overlap_selection(worker_type, overlap_blocks_lost);
128	                    }
129	                    tracing::debug!(
130	                        request_id,
131	                        worker_type,
132	                        selected_worker_id = selection.selected_worker.worker_id,
133	                        selected_dp_rank = selection.selected_worker.dp_rank,
134	                        selected_overlap_blocks = selection.selected_overlap_blocks,
135	                        highest_overlap_worker_id = selection.highest_overlap_worker.worker_id,
136	                        highest_overlap_dp_rank = selection.highest_overlap_worker.dp_rank,
137	                        highest_overlap_blocks = selection.highest_overlap_blocks,
138	                        overlap_blocks_lost,
139	                        "Router selected a worker with lower KV cache overlap"
140	                    );
141	                });
142	            if !inner.set_non_max_overlap_selection_observer(locality_observer) {
143	                return Err(KvSchedulerError::InitFailed(
144	                    "non-max-overlap observer is already installed".to_string(),
145	                ));
146	            }
147	        }
148	
149	        let metrics_scheduler = Arc::clone(&inner);
150	        let background_metrics = queue_metrics.clone();
151	        let metrics_cancel_token = cancellation_token.child_token();
152	        let mut queue_updates = inner.subscribe_queue_updates();
153	        tokio::spawn(async move {
154	            let mut recheck_interval = tokio::time::interval(Duration::from_secs(60));
155	            update_queue_metrics(&background_metrics, |class_index| {
156	                metrics_scheduler.class_queue_stats(class_index)
157	            });
158	
159	            loop {
160	                tokio::select! {
161	                    _ = metrics_cancel_token.cancelled() => break,
162	                    result = queue_updates.changed() => {
163	                        if result.is_err() {
164	                            break;
165	                        }
166	                        update_queue_metrics(&background_metrics, |class_index| {
167	                            metrics_scheduler.class_queue_stats(class_index)
168	                        });
169	                    }
170	                    _ = recheck_interval.tick() => {
171	                        update_queue_metrics(&background_metrics, |class_index| {
172	                            metrics_scheduler.class_queue_stats(class_index)
173	                        });
174	                    }
175	                }
176	            }
177	        });
178	
179	        Ok(Self {
180	            inner,
181	            queue_metrics,
182	            queue_metric_indices,
183	        })
184	    }
