333	    fn observe_schedule_result(&self, response: &Result<SchedulingResponse, KvSchedulerError>) {
334	        if let Err(KvSchedulerError::QueueRejected(rejection)) = response
335	            && let Some(metrics) = self
336	                .queue_metric_indices
337	                .get(&rejection.policy_class)
338	                .and_then(|index| self.queue_metrics.get(*index))
339	        {
340	            match rejection.limit_kind {
341	                dynamo_kv_router::scheduling::QueueLimitKind::Requests => {
342	                    metrics.request_limit_rejections.inc();
343	                }
344	                dynamo_kv_router::scheduling::QueueLimitKind::RawIslTokens => {
345	                    metrics.raw_isl_limit_rejections.inc();
346	                }
347	                dynamo_kv_router::scheduling::QueueLimitKind::CachedTokens => {
348	                    metrics.cached_token_limit_rejections.inc();
349	                }
350	            }
351	        }
352	        self.update_queue_metrics();
353	    }
