444	fn update_queue_metrics(
445	    handles: &[RouterQueueMetricHandles],
446	    mut stats_for: impl FnMut(usize) -> Option<dynamo_kv_router::queue::ClassQueueStats>,
447	) {
448	    for (class_index, handles) in handles.iter().enumerate() {
449	        let Some(stats) = stats_for(class_index) else {
450	            debug_assert!(
451	                false,
452	                "missing queue counters for policy class {class_index}"
453	            );
454	            continue;
455	        };
456	        handles.pending_requests.set(stats.pending_count as i64);
457	        handles
458	            .pending_isl_tokens
459	            .set(stats.pending_isl_tokens as i64);
460	        handles
461	            .pending_cached_tokens
462	            .set(stats.pending_cached_tokens as i64);
463	    }
464	}
