276	        if is_direct && explicit.is_none() {
277	            return Err(invalid_argument(format!(
278	                "worker ID required for {phase} request in Direct routing mode"
279	            )));
280	        }
281	        let has_affinity_session = self.affinity.is_some() && affinity_id(&request)?.is_some();
282	        let is_query_only = request.get_annotation_value("query_instance_id").is_some();
283	        let (lora_target, lora_fallback, lora_load) =
284	            match self.select_lora_target(request.content())? {
285	                Some(selection) => (
286	                    Some(selection.target),
287	                    Some(selection.allowed_fallback),
288	                    Some(selection.load_guard),
289	                ),
