135	    /// Select a worker using either a phase-specific pin or KV overlap.
136	    pub(super) async fn select_worker(
137	        &self,
138	        context_id: &str,
139	        request: &PreprocessedRequest,
140	        routing_parts: RoutingRequestParts<'_>,
141	        phase: RequestPhase,
142	        is_query_only: bool,
143	        options: SelectionOptions,
144	    ) -> Result<WorkerSelection, Error> {
145	        let _nvtx_select = dynamo_nvtx_range!("route.select_worker");
146	        let routing = request.routing.as_ref();
147	        let explicit_pin = pinned_worker_hint(phase, routing);
148	        let lora_name = routing.and_then(|routing| routing.lora_name.clone());
149	        let cache_namespace = routing.and_then(|routing| routing.cache_namespace.clone());
150	        let priority_jump = routing
151	            .and_then(|routing| routing.priority_jump)
152	            .unwrap_or(0.0);
153	        let strict_priority = routing
154	            .and_then(|routing| routing.strict_priority)
155	            .unwrap_or(0);
156	        let expected_output_tokens = routing.and_then(|routing| routing.expected_output_tokens);
157	        let routing_constraints = routing
158	            .and_then(|routing| routing.routing_constraints.clone())
159	            .unwrap_or_default();
160	        let mut allowed_worker_ids = routing.and_then(|routing| routing.allowed_worker_ids.clone());
161	        let migration_excluded_worker_ids = request
162	            .migration_state
163	            .as_ref()
164	            .map(|state| state.excluded_worker_ids())
165	            .unwrap_or_default();
166	        if explicit_pin.is_none() && !migration_excluded_worker_ids.is_empty() {
167	            let workers = self.kv_router().workers_with_configs.borrow();
168	            let eligible =
169	                allowed_worker_ids.get_or_insert_with(|| workers.keys().copied().collect());
170	            eligible.retain(|worker_id| {
171	                workers.get(worker_id).is_some_and(|config| {
172	                    routing_constraints.is_compatible_with_worker_taints(&config.taints)
173	                }) && !migration_excluded_worker_ids.contains(worker_id)
174	            });
175	            if eligible.is_empty()
176	                && let Some(error) = request
177	                    .migration_state
178	                    .as_ref()
179	                    .and_then(|state| state.exhausted_error())
180	            {
181	                return Err(anyhow::anyhow!(error));
182	            }
183	        }
184	        let return_routing_hashes =
185	            !is_query_only && self.kv_router().indexer().records_routing_decisions();
186	        let SelectionOptions {
187	            affinity_target,
188	            policy_class,
189	            session_context,
190	        } = options;
191	        let worker_only_affinity = affinity_target.filter(|target| target.dp_rank.is_none());
192	        if let Some(target) = worker_only_affinity {
193	            match &mut allowed_worker_ids {
194	                Some(allowed_workers) => {
195	                    allowed_workers.retain(|worker_id| *worker_id == target.worker_id);
196	                }
197	                None => {
198	                    allowed_worker_ids = Some(HashSet::from([target.worker_id]));
199	                }
200	            }
201	        }
202	        let explicit_pin = match (explicit_pin, worker_only_affinity) {
203	            (Some((worker_id, None)), Some(affinity_target))
204	                if worker_id == affinity_target.worker_id =>
205	            {
206	                // A worker-only session binding allows the KV scheduler to select this
207	                // request's rank, so do not turn a matching worker-only request hint into an
208	                // exact-rank pin.
209	                None
210	            }
211	            (explicit_pin, _) => explicit_pin,
212	        };
213	        let affinity_pin = affinity_target.and_then(|target| {
214	            target
215	                .dp_rank
216	                .map(|dp_rank| (target.worker_id, Some(dp_rank)))
217	        });
218	        let Some((pinned_worker_id, requested_dp_rank)) =
219	            merge_affinity_pin(explicit_pin, affinity_pin)
220	        else {
221	            let _nvtx_kv = dynamo_nvtx_range!("route.kv_match");
222	            let selection = self
223	                .select_best_match(BestMatchArgs {
224	                    context_id,
225	                    routing_parts,
226	                    router_config_override: request.router_config_override.as_ref(),
227	                    update_states: !is_query_only,
228	                    return_routing_hashes,
229	                    lora_name,
230	                    cache_namespace,
231	                    priority_jump,
232	                    strict_priority,
233	                    policy_class,
234	                    session_context,
235	                    expected_output_tokens,
236	                    pinned_worker: None,
237	                    allowed_worker_ids,
238	                    routing_constraints: routing_constraints.clone(),
239	                })
240	                .await?;
241	
242	            if !is_query_only {
243	                let total_blocks = routing_parts
244	                    .token_ids
245	                    .len()
246	                    .div_ceil(self.kv_router().block_size() as usize);
247	                // tests/utils/router_logs.py parses the structured fields on this event.
248	                tracing::debug!(
249	                    request_id = %context_id,
250	                    worker_id = selection.worker.worker_id,
251	                    dp_rank = selection.worker.dp_rank,
252	                    overlap_blocks = selection.overlap_amount,
253	                    total_blocks,
254	                    "[ROUTING] Best: worker_{} dp_rank={} with {}/{} blocks overlap",
255	                    selection.worker.worker_id,
256	                    selection.worker.dp_rank,
257	                    selection.overlap_amount,
258	                    total_blocks,
259	                );
260	            }
261	
262	            return Ok(selection);
263	        };
264	        let cache_namespace = routing.and_then(|routing| routing.cache_namespace.clone());
265	
266	        let pinned_worker = resolve_pinned_worker_rank(
267	            pinned_worker_id,
268	            requested_dp_rank,
269	            self.kv_router().unique_dp_rank_for_worker(pinned_worker_id),
270	        )?;
271	        {
272	            let configs = self.kv_router().workers_with_configs.borrow();
273	            let eligibility = RoutingEligibility::new(
274	                allowed_worker_ids.as_ref(),
275	                None,
276	                Some(pinned_worker),
277	                &routing_constraints,
278	            );
279	            if let Err(error) = eligibility.validate_worker_rank(&configs, pinned_worker) {
280	                return Err(anyhow::anyhow!(
281	                    "Pinned worker {} dp_rank {} is not eligible: {error}",
282	                    pinned_worker.worker_id,
283	                    pinned_worker.dp_rank
284	                ));
285	            }
286	        }
287	
288	        tracing::debug!(
289	            worker_id = pinned_worker.worker_id,
290	            dp_rank = pinned_worker.dp_rank,
291	            ?phase,
292	            "Routing to specified worker"
293	        );
294	
295	        self.select_best_match(BestMatchArgs {
296	            context_id,
297	            routing_parts,
298	            router_config_override: request.router_config_override.as_ref(),
299	            update_states: !is_query_only,
300	            return_routing_hashes,
301	            lora_name,
302	            cache_namespace,
303	            priority_jump,
304	            strict_priority,
305	            policy_class,
306	            session_context,
307	            expected_output_tokens,
308	            pinned_worker: Some(pinned_worker),
309	            allowed_worker_ids,
310	            routing_constraints,
311	        })
312	        .await
313	    }
314	}
