316	fn merge_affinity_pin(
317	    explicit: Option<(u64, Option<u32>)>,
318	    affinity: Option<(u64, Option<u32>)>,
319	) -> Option<(u64, Option<u32>)> {
320	    match (explicit, affinity) {
321	        (Some((worker_id, None)), Some((affinity_worker_id, affinity_rank)))
322	            if worker_id == affinity_worker_id =>
323	        {
324	            Some((worker_id, affinity_rank))
325	        }
326	        (Some(explicit), _) => Some(explicit),
327	        (None, affinity) => affinity,
328	    }
329	}
330	
331	fn resolve_pinned_worker_rank(
332	    worker_id: WorkerId,
333	    requested_dp_rank: Option<u32>,
334	    unique_dp_rank: Option<u32>,
335	) -> Result<WorkerWithDpRank, Error> {
336	    let Some(dp_rank) = requested_dp_rank.or(unique_dp_rank) else {
337	        return Err(anyhow::anyhow!(
338	            "Pinned worker {worker_id} requires an explicit dp_rank because it has multiple or unknown DP ranks"
339	        ));
340	    };
341	
342	    Ok(WorkerWithDpRank::new(worker_id, dp_rank))
343	}
344	
345	fn pinned_worker_hint(
346	    phase: RequestPhase,
347	    routing: Option<&RoutingHints>,
348	) -> Option<(u64, Option<u32>)> {
349	    let routing = routing?;
350	    match phase {
351	        RequestPhase::Prefill => {
352	            let worker_id = routing.prefill_worker_id.or(routing.backend_instance_id)?;
353	            let dp_rank = routing.prefill_dp_rank.or(routing.dp_rank);
354	            Some((worker_id, dp_rank))
355	        }
356	        RequestPhase::Decode => {
357	            let worker_id = routing.decode_worker_id.or(routing.backend_instance_id)?;
358	            Some((worker_id, routing.dp_rank))
359	        }
360	        RequestPhase::Aggregated => {
361	            let worker_id = routing.decode_worker_id.or(routing.backend_instance_id)?;
362	            Some((worker_id, routing.dp_rank))
363	        }
364	    }
365	}
