23	fn softmax_sample_entries<T: Copy>(
24	    entries: Vec<(T, f64)>,
25	    temperature: f64,
26	    sample: f64,
27	) -> (T, f64) {
28	    assert!(!entries.is_empty(), "Empty logits for softmax sampling");
29	
30	    let mut probabilities = Vec::with_capacity(entries.len());
31	    let row = softmax_sample_index(
32	        &entries,
33	        |(_, cost)| *cost,
34	        temperature,
35	        sample,
36	        &mut probabilities,
37	    );
38	    entries[row]
39	}
