41	fn softmax_sample_index<T>(
42	    entries: &[T],
43	    cost: impl Fn(&T) -> f64,
44	    temperature: f64,
45	    sample: f64,
46	    probabilities: &mut Vec<f64>,
47	) -> usize {
48	    assert!(!entries.is_empty(), "Empty entries for softmax sampling");
49	    debug_assert_ne!(temperature, 0.0);
50	
51	    let (min_cost, max_cost) = entries
52	        .iter()
53	        .map(&cost)
54	        .fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), cost| {
55	            (lo.min(cost), hi.max(cost))
56	        });
57	
58	    probabilities.clear();
59	    if min_cost == max_cost {
60	        probabilities.resize(entries.len(), 1.0 / entries.len() as f64);
61	    } else {
62	        let range = max_cost - min_cost;
63	        let magnitude = if range.is_finite() {
64	            1.0
65	        } else {
66	            min_cost.abs().max(max_cost.abs())
67	        };
68	        let min_normalized = min_cost / magnitude;
69	        let scale = -1.0 / ((max_cost / magnitude - min_normalized) * temperature);
70	        let max_scaled = min_normalized * scale;
71	        probabilities.extend(
72	            entries
73	                .iter()
74	                .map(|entry| (cost(entry) / magnitude * scale - max_scaled).exp()),
75	        );
76	    }
77	
78	    let sum: f64 = probabilities.iter().sum();
79	    for probability in probabilities.iter_mut() {
80	        *probability /= sum;
81	    }
82	    let mut cumulative = 0.0;
83	    for (row, probability) in probabilities.iter().enumerate() {
84	        cumulative += probability;
85	        if sample <= cumulative {
86	            return row;
87	        }
88	    }
89	    entries.len() - 1
90	}
