274	    fn worker_logit(
275	        &self,
276	        context: &WorkerSelectionContext<'_>,
277	        default_context: DefaultScoringContext,
278	        row: &WorkerCandidate,
279	        formula_name: &'static str,
280	    ) -> f64 {
281	        let kv_router_config = self.kv_router_config.borrow();
282	        let weights = context.weights;
283	        let worker = row.worker;
284	        let cache = &row.cache;
285	        let load = &row.load;
286	        let effective_overlap_blocks = cache.effective_overlap_blocks;
287	        let device_overlap_blocks = cache.device_overlap_blocks;
288	        let shared_beyond_device_blocks = cache.shared_beyond_device_blocks;
289	        let shared_overlap_blocks =
290	            weights.shared_cache_multiplier * shared_beyond_device_blocks as f64;
291	        // Normalize backlog above the least-loaded eligible worker by this request's
292	        // size. The rational decay softly trades cache locality for prefill balance,
293	        // while leaving workers at the load floor with their full device credit.
294	        let overlap_credit_decay =
295	            if context.track_prefill_tokens && weights.overlap_score_credit_decay > 0.0 {
296	                let excess_active_prefill_blocks = load
297	                    .active_prefill_tokens
298	                    .saturating_sub(default_context.min_active_prefill_tokens)
299	                    as f64
300	                    / context.block_size as f64;
301	                let normalized_prefill_load =
302	                    excess_active_prefill_blocks / context.request_blocks as f64;
303	                1.0 / (1.0 + weights.overlap_score_credit_decay * normalized_prefill_load)
304	            } else {
305	                1.0
306	            };
307	        let effective_overlap_score_credit = weights.overlap_score_credit * overlap_credit_decay;
308	        let overlap_credit_blocks = effective_overlap_score_credit * device_overlap_blocks
309	            + kv_router_config.host_cache_hit_weight * cache.host_overlap_blocks
310	            + kv_router_config.disk_cache_hit_weight * cache.disk_overlap_blocks
311	            + shared_overlap_blocks;
312	        let decode_cost_blocks = load.decode_cost_blocks;
313	        let active_request_cost_blocks =
314	            kv_router_config.decode_active_request_weight * load.active_requests as f64;
315	
316	        // Decode routers normally force `overlap_score_credit=0` through the
317	        // per-request override, which preserves load-only disagg routing. When
318	        // conditional disagg leaves a positive overlap credit in place, prefer
319	        // cache-hot decode workers while still charging decode backlog.
320	        if self.worker_type == "decode"
321	            && !context.track_prefill_tokens
322	            && weights.overlap_score_credit > 0.0
323	        {
324	            // Clamp at zero because downstream taint multipliers assume non-negative scores.
325	            // This loses ordering between workers whose overlap fully offsets decode load, but
326	            // avoids inverting taint preference among negative-score workers.
327	            let overlap_adjusted_decode_blocks =
328	                (decode_cost_blocks - overlap_credit_blocks).max(0.0);
329	            let logit = overlap_adjusted_decode_blocks + active_request_cost_blocks;
330	            // Stamped for the same reason as the two rows below: this row is emitted from the
331	            // `SchedulerQueueActor` task, so the logging layer cannot attach request identity to
332	            // it, and this branch returns early without reaching them.
333	            tracing::debug!(
334	                request_id = context.request_id,
335	                worker_type = self.worker_type,
336	                "{formula_name} for worker_id={} dp_rank={:?} with {effective_overlap_blocks:.2} effective cached blocks: {logit:.3} \
337	                 = max(0, decode_blocks - overlap_credit_blocks) + active_request_cost_blocks \
338	                 = max(0, {decode_cost_blocks:.3} - {overlap_credit_blocks:.3}) + {active_request_cost_blocks:.3}",
339	                worker.worker_id,
340	                worker.dp_rank,
341	            );
342	            return logit;
343	        }
344	
345	        let adjusted_prefill_blocks = (load.raw_prefill_blocks - overlap_credit_blocks).max(0.0);
346	        let prefill_cost_blocks = weights.prefill_load_scale * adjusted_prefill_blocks;
347	        let logit = prefill_cost_blocks + decode_cost_blocks + active_request_cost_blocks;
348	
349	        // These rows are emitted from the `SchedulerQueueActor` task, which `scheduling::queue`
350	        // spawns without the caller's request span, so the logging layer cannot attach
351	        // `x_request_id`/`trace_id` to them. Stamp the identity the row needs to be self-joining:
352	        // `request_id` is the same value `[ROUTING] Best` logs, and `worker_type` separates the
353	        // prefill-pool and decode-pool decisions that interleave into one log. Both are evaluated
354	        // inside the macro so they cost nothing when DEBUG is disabled.
355	        if shared_beyond_device_blocks > 0 {
356	            tracing::debug!(
357	                request_id = context.request_id,
358	                worker_type = self.worker_type,
359	                "{formula_name} for worker_id={} dp_rank={:?} with {effective_overlap_blocks:.2} effective cached blocks, \
360	                 {} shared blocks beyond device (multiplier={shared_cache_multiplier:.2}): {logit:.3} \
361	                 = prefill_load_scale * adjusted_prefill_blocks + decode_blocks + active_request_cost_blocks \
362	                 = {prefill_load_scale:.3} * {adjusted_prefill_blocks:.3} + {decode_cost_blocks:.3} + {active_request_cost_blocks:.3} \
363	                 (raw_prefill_blocks: {:.3}, overlap_credit_blocks: {overlap_credit_blocks:.3}, \
364	                 overlap_credit_decay: {overlap_credit_decay:.3})",
365	                worker.worker_id,
366	                worker.dp_rank,
367	                shared_beyond_device_blocks,
368	                load.raw_prefill_blocks,
369	                shared_cache_multiplier = weights.shared_cache_multiplier,
370	                prefill_load_scale = weights.prefill_load_scale
371	            );
372	        } else {
373	            tracing::debug!(
374	                request_id = context.request_id,
375	                worker_type = self.worker_type,
376	                "{formula_name} for worker_id={} dp_rank={:?} with {effective_overlap_blocks:.2} effective cached blocks: {logit:.3} \
377	                 = prefill_load_scale * adjusted_prefill_blocks + decode_blocks + active_request_cost_blocks \
378	                 = {prefill_load_scale:.3} * {adjusted_prefill_blocks:.3} + {decode_cost_blocks:.3} + {active_request_cost_blocks:.3} \
379	                 (raw_prefill_blocks: {:.3}, overlap_credit_blocks: {overlap_credit_blocks:.3}, \
380	                 overlap_credit_decay: {overlap_credit_decay:.3})",
381	                worker.worker_id,
382	                worker.dp_rank,
383	                load.raw_prefill_blocks,
384	                prefill_load_scale = weights.prefill_load_scale
385	            );
386	        }
387	
388	        logit
389	    }
