391	    #[inline]
392	    fn worker_cost(
393	        &self,
394	        context: &WorkerSelectionContext<'_>,
395	        default_context: DefaultScoringContext,
396	        row: &WorkerCandidate,
397	    ) -> f64 {
398	        let base_score = self.worker_logit(context, default_context, row, "Formula");
399	        match row.preferred_taint_multiplier {
400	            // NOTE: This multiplicative bias assumes a non-negative score. Negative
401	            // overlap scores expose its pre-existing sign sensitivity; keep it for now.
402	            Some(multiplier) => base_score * multiplier,
403	            None => base_score,
404	        }
405	    }
406	}
