418	fn minimum_cost_index(
419	    candidates: &[ScoredWorkerCandidate],
420	    mut random_index: impl FnMut(usize) -> usize,
421	) -> usize {
422	    let mut best_row = 0;
423	    let mut best_cost = f64::INFINITY;
424	    let mut tie_count = 0;
425	    for (row, candidate) in candidates.iter().enumerate() {
426	        let cost = candidate.cost;
427	        if cost < best_cost {
428	            best_row = row;
429	            best_cost = cost;
430	            tie_count = 1;
431	        } else if cost == best_cost {
432	            tie_count += 1;
433	            if random_index(tie_count) == 0 {
434	                best_row = row;
435	            }
436	        }
437	    }
438	    best_row
439	}
