441	#[inline(always)]
442	pub(super) fn pick_default_worker<C: WorkerConfigLike>(
443	    scorer: &DefaultWorkerScorer<&KvRouterConfig>,
444	    picker: &DefaultWorkerPicker,
445	    input: &MaterializedSelectionInput<'_>,
446	    workers: &HashMap<WorkerId, C>,
447	    request: &SchedulingRequest,
448	    eligibility: RoutingEligibility<'_>,
449	) -> Option<(WorkerWithDpRank, f64)> {
450	    let default_context =
451	        DefaultScoringContext::new(workers, request, eligibility, input.context.weights);
452	    if let Some(worker) = eligibility.pinned_worker() {
453	        let row = default_row(input, default_context, worker, None);
454	        return Some((
455	            worker,
456	            scorer.worker_logit(&input.context, default_context, &row, "Pinned formula"),
457	        ));
458	    }
459	
460	    let temperature = input
461	        .context
462	        .router_temperature_override
463	        .unwrap_or(scorer.kv_router_config.router_temperature);
464	    let get_score = |worker, config: &C| {
465	        let preferred_taint_multiplier = request
466	            .routing_constraints
467	            .preferred_taint_multiplier(config.taints());
468	        scorer.worker_cost(
469	            &input.context,
470	            default_context,
471	            &default_row(input, default_context, worker, preferred_taint_multiplier),
472	        )
473	    };
474	
475	    #[cfg(any(test, feature = "bench"))]
476	    if let Some(rng) = &picker.deterministic_rng {
477	        let mut candidates = Vec::new();
478	        eligibility.for_each_eligible_worker_rank(workers, |worker, _| candidates.push(worker));
479	        candidates.sort_unstable_by_key(|worker| (worker.worker_id, worker.dp_rank));
480	        if candidates.is_empty() {
481	            return None;
482	        }
483	
484	        let mut rng = rng.lock();
485	        let get_candidate_score = |worker| get_score(worker, &workers[&worker.worker_id]);
486	        if temperature == 0.0 {
487	            let mut best_worker = None;
488	            let mut best_cost = f64::INFINITY;
489	            let mut tie_count = 0;
490	            for worker in candidates {
491	                let cost = get_candidate_score(worker);
492	                if cost < best_cost {
493	                    best_worker = Some(worker);
494	                    best_cost = cost;
495	                    tie_count = 1;
496	                } else if cost == best_cost {
497	                    tie_count += 1;
498	                    if rng.usize(0..tie_count) == 0 {
499	                        best_worker = Some(worker);
500	                    }
501	                }
502	            }
503	            return best_worker.map(|worker| (worker, best_cost));
504	        }
505	
506	        let entries = candidates
507	            .into_iter()
508	            .map(|worker| (worker, get_candidate_score(worker)))
509	            .collect();
510	        return Some(softmax_sample_entries(entries, temperature, rng.f64()));
511	    }
512	
513	    if temperature == 0.0 {
514	        let mut best_worker = None;
515	        let mut best_cost = f64::INFINITY;
516	        let mut tie_count = 0;
517	        eligibility.for_each_eligible_worker_rank(workers, |worker, config| {
518	            let cost = get_score(worker, config);
519	            if cost < best_cost {
520	                best_worker = Some(worker);
521	                best_cost = cost;
522	                tie_count = 1;
523	            } else if cost == best_cost {
524	                tie_count += 1;
525	                if fastrand::usize(0..tie_count) == 0 {
526	                    best_worker = Some(worker);
527	                }
528	            }
529	        });
530	        return best_worker.map(|worker| (worker, best_cost));
531	    }
532	
533	    let mut scratch = picker.softmax_scratch.lock();
534	    scratch.entries.clear();
535	    eligibility.for_each_eligible_worker_rank(workers, |worker, config| {
536	        scratch.entries.push((worker, get_score(worker, config)));
537	    });
538	    if scratch.entries.is_empty() {
539	        None
540	    } else {
541	        let DefaultSoftmaxScratch {
542	            entries,
543	            probabilities,
544	        } = &mut *scratch;
545	        let row = softmax_sample_index(
546	            entries,
547	            |(_, cost)| *cost,
548	            temperature,
549	            fastrand::f64(),
550	            probabilities,
551	        );
552	        Some(entries[row])
553	    }
554	}
