570	impl WorkerPicker for DefaultWorkerPicker {
571	    fn pick(
572	        &mut self,
573	        context: &WorkerSelectionContext<'_>,
574	        input: WorkerInputView<'_>,
575	    ) -> Result<usize, WorkerSelectionPolicyError> {
576	        let candidates = input.candidates();
577	        let temperature = context
578	            .router_temperature_override
579	            .unwrap_or(self.default_temperature);
580	        #[cfg(any(test, feature = "bench"))]
581	        if let Some(rng) = &self.deterministic_rng {
582	            let mut rng = rng.lock();
583	            if temperature == 0.0 {
584	                return Ok(minimum_cost_index(candidates, |count| rng.usize(0..count)));
585	            }
586	            let sample = rng.f64();
587	            drop(rng);
588	            return Ok(softmax_sample_index(
589	                candidates,
590	                |candidate| candidate.cost,
591	                temperature,
592	                sample,
593	                &mut self.softmax_scratch.get_mut().probabilities,
594	            ));
595	        }
596	        if temperature == 0.0 {
597	            return Ok(minimum_cost_index(candidates, |count| {
598	                fastrand::usize(0..count)
599	            }));
600	        }
601	        Ok(softmax_sample_index(
602	            candidates,
603	            |candidate| candidate.cost,
604	            temperature,
605	            fastrand::f64(),
606	            &mut self.softmax_scratch.get_mut().probabilities,
607	        ))
608	    }
609	}
